# ============================================================================\n# REAL-TIME ANALYTICS ENGINE - STREAMING LEGISLATIVE ANALYSIS\n# ============================================================================\n#\n# Real-time processing of Brazilian legislative documents\n# Event-driven analytics, live dashboard updates, automated alerts\n# Continuous model updates with incremental learning\n#\n# Author: Data Science Consultant\n# Date: 2025-08-29\n# Version: 1.0 Production-Ready\n# ============================================================================\n\nlibrary(R6)\nlibrary(reticulate)\nlibrary(jsonlite)\nlibrary(data.table)\nlibrary(future)\nlibrary(promises)\nlibrary(shiny)\nlibrary(DBI)\n\ncat(\"🚀 Real-Time Analytics Engine v1.0 initialized\\n\")\n\n# ============================================================================\n# 1. STREAMING DATA PROCESSOR\n# ============================================================================\n\n#' Real-Time Document Stream Processor\n#' Processes incoming legislative documents in real-time with event-driven analytics\nRealTimeProcessor <- R6Class(\"RealTimeProcessor\",\n  public = list(\n    # Configuration\n    batch_size = 50,\n    processing_interval = 5,  # seconds\n    max_memory_mb = 500,\n    \n    # State\n    is_running = FALSE,\n    processed_count = 0,\n    error_count = 0,\n    \n    # Storage\n    incoming_queue = NULL,\n    processing_buffer = NULL,\n    alert_queue = NULL,\n    \n    # Models and analytics\n    feature_extractor = NULL,\n    classifier = NULL,\n    trend_analyzer = NULL,\n    alert_system = NULL,\n    \n    # Callbacks\n    on_document_processed = NULL,\n    on_alert_generated = NULL,\n    on_error = NULL,\n    \n    initialize = function(config = list()) {\n      cat(\"🔧 Initializing Real-Time Processor...\\n\")\n      \n      # Apply configuration\n      for (key in names(config)) {\n        if (key %in% names(self)) {\n          self[[key]] <- config[[key]]\n        }\n      }\n      \n      # Initialize data structures\n      self$incoming_queue <- data.table()\n      self$processing_buffer <- data.table()\n      self$alert_queue <- data.table()\n      \n      # Initialize analytics components\n      self$initialize_analytics_components()\n      \n      cat(\"✅ Real-Time Processor initialized\\n\")\n    },\n    \n    initialize_analytics_components = function() {\n      cat(\"   🧠 Loading analytics components...\\n\")\n      \n      # Feature extractor (lightweight version)\n      self$feature_extractor <- list(\n        extract_features = function(documents) {\n          # Simplified real-time feature extraction\n          tryCatch({\n            dt <- as.data.table(documents)\n            \n            dt[, `:=`(\n              # Basic features\n              char_count = nchar(title),\n              word_count = stringi::stri_count_words(title),\n              \n              # Transport relevance (fast regex)\n              transport_score = stringi::stri_count_regex(\n                tolower(title),\n                \"\\\\b(transport|rodovia|ferrovia|porto|aeroporto|antt|antaq|anac)\\\\b\"\n              ),\n              \n              # Legal type (simplified)\n              legal_type = fcase(\n                stringi::stri_detect_regex(tolower(title), \"\\\\blei\\\\b\"), \"lei\",\n                stringi::stri_detect_regex(tolower(title), \"\\\\bdecreto\\\\b\"), \"decreto\",\n                stringi::stri_detect_regex(tolower(title), \"\\\\bresolução\\\\b\"), \"resolucao\",\n                stringi::stri_detect_regex(tolower(title), \"\\\\bportaria\\\\b\"), \"portaria\",\n                default = \"outros\"\n              ),\n              \n              # Urgency indicators\n              urgency_score = stringi::stri_count_regex(\n                tolower(title),\n                \"\\\\b(urgente|emergencial|imediato|prazo)\\\\b\"\n              ),\n              \n              # Processing timestamp\n              processed_at = Sys.time()\n            )]\n            \n            return(dt)\n          }, error = function(e) {\n            warning(\"Feature extraction failed: \", e$message)\n            return(documents)\n          })\n        }\n      )\n      \n      # Real-time classifier (rule-based for speed)\n      self$classifier <- list(\n        classify = function(features) {\n          tryCatch({\n            features[, `:=`(\n              category = fcase(\n                transport_score > 0, \"Transporte\",\n                legal_type == \"lei\", \"Legislação\",\n                legal_type == \"decreto\", \"Regulamentação\",\n                default = \"Geral\"\n              ),\n              \n              priority = fcase(\n                urgency_score > 1, \"Alta\",\n                transport_score > 2, \"Alta\",\n                transport_score > 0, \"Média\",\n                default = \"Baixa\"\n              ),\n              \n              confidence = pmin(1.0, (\n                (transport_score * 0.4) +\n                (urgency_score * 0.3) +\n                (ifelse(char_count > 50, 1, 0) * 0.3)\n              ))\n            )]\n            \n            return(features)\n          }, error = function(e) {\n            warning(\"Classification failed: \", e$message)\n            return(features)\n          })\n        }\n      )\n      \n      # Trend analyzer (simplified)\n      self$trend_analyzer <- list(\n        analyze_trends = function(recent_data) {\n          if (nrow(recent_data) < 10) {\n            return(list(\n              trend_detected = FALSE,\n              trend_type = \"insufficient_data\",\n              confidence = 0\n            ))\n          }\n          \n          tryCatch({\n            # Simple trend detection based on recent activity\n            recent_data[, hour := hour(processed_at)]\n            hourly_counts <- recent_data[, .N, by = hour]\n            \n            if (nrow(hourly_counts) >= 3) {\n              # Calculate trend slope\n              trend_model <- lm(N ~ hour, data = hourly_counts)\n              slope <- coef(trend_model)[2]\n              \n              list(\n                trend_detected = abs(slope) > 0.5,\n                trend_type = ifelse(slope > 0.5, \"increasing\", \n                                  ifelse(slope < -0.5, \"decreasing\", \"stable\")),\n                trend_strength = abs(slope),\n                confidence = min(1.0, abs(slope) / 2)\n              )\n            } else {\n              list(trend_detected = FALSE, trend_type = \"stable\", confidence = 0.5)\n            }\n          }, error = function(e) {\n            list(trend_detected = FALSE, trend_type = \"error\", confidence = 0)\n          })\n        }\n      )\n      \n      # Alert system\n      self$alert_system <- list(\n        check_alerts = function(processed_data) {\n          alerts <- list()\n          \n          tryCatch({\n            # High-priority transport documents\n            high_priority_transport <- processed_data[\n              category == \"Transporte\" & priority == \"Alta\"\n            ]\n            \n            if (nrow(high_priority_transport) > 0) {\n              alerts[[length(alerts) + 1]] <- list(\n                type = \"high_priority_transport\",\n                severity = \"high\",\n                message = paste(\"Detected\", nrow(high_priority_transport), \n                              \"high-priority transport documents\"),\n                count = nrow(high_priority_transport),\n                documents = high_priority_transport[, .(id, title, priority)],\n                timestamp = Sys.time()\n              )\n            }\n            \n            # Unusual activity volume\n            if (nrow(processed_data) > self$batch_size * 2) {\n              alerts[[length(alerts) + 1]] <- list(\n                type = \"high_volume\",\n                severity = \"medium\",\n                message = paste(\"High document volume detected:\", nrow(processed_data), \"documents\"),\n                count = nrow(processed_data),\n                timestamp = Sys.time()\n              )\n            }\n            \n            # New legal types\n            unique_types <- unique(processed_data$legal_type)\n            if (length(unique_types) > 3) {\n              alerts[[length(alerts) + 1]] <- list(\n                type = \"diverse_legal_types\",\n                severity = \"low\",\n                message = paste(\"Diverse legal document types detected:\", \n                              paste(unique_types, collapse = \", \")),\n                types = unique_types,\n                timestamp = Sys.time()\n              )\n            }\n            \n            return(alerts)\n          }, error = function(e) {\n            warning(\"Alert generation failed: \", e$message)\n            return(list())\n          })\n        }\n      )\n    },\n    \n    start = function() {\n      if (self$is_running) {\n        warning(\"Processor is already running\")\n        return(invisible(self))\n      }\n      \n      cat(\"🚀 Starting real-time processing...\\n\")\n      self$is_running <- TRUE\n      \n      # Start processing loop in background\n      future({\n        while (self$is_running) {\n          self$process_batch()\n          Sys.sleep(self$processing_interval)\n        }\n      })\n      \n      cat(\"✅ Real-time processor started\\n\")\n      invisible(self)\n    },\n    \n    stop = function() {\n      cat(\"⏹️  Stopping real-time processor...\\n\")\n      self$is_running <- FALSE\n      cat(\"✅ Real-time processor stopped\\n\")\n      invisible(self)\n    },\n    \n    add_document = function(document) {\n      if (!self$is_running) {\n        warning(\"Processor is not running\")\n        return(invisible(self))\n      }\n      \n      # Add to incoming queue\n      new_doc <- as.data.table(document)\n      new_doc[, received_at := Sys.time()]\n      self$incoming_queue <- rbind(self$incoming_queue, new_doc, fill = TRUE)\n      \n      invisible(self)\n    },\n    \n    add_documents = function(documents) {\n      if (!self$is_running) {\n        warning(\"Processor is not running\")\n        return(invisible(self))\n      }\n      \n      new_docs <- as.data.table(documents)\n      new_docs[, received_at := Sys.time()]\n      self$incoming_queue <- rbind(self$incoming_queue, new_docs, fill = TRUE)\n      \n      cat(\"📥 Added\", nrow(new_docs), \"documents to processing queue\\n\")\n      invisible(self)\n    },\n    \n    process_batch = function() {\n      if (nrow(self$incoming_queue) == 0) {\n        return(invisible(self))\n      }\n      \n      # Check memory usage\n      current_memory <- object.size(self$incoming_queue) / (1024^2)\n      if (current_memory > self$max_memory_mb) {\n        warning(\"Memory limit exceeded, clearing old data\")\n        # Keep only most recent documents\n        self$incoming_queue <- tail(self$incoming_queue, self$batch_size * 2)\n        gc()\n      }\n      \n      # Get batch to process\n      batch_size <- min(self$batch_size, nrow(self$incoming_queue))\n      current_batch <- head(self$incoming_queue, batch_size)\n      self$incoming_queue <- tail(self$incoming_queue, -batch_size)\n      \n      if (nrow(current_batch) == 0) {\n        return(invisible(self))\n      }\n      \n      cat(\"⚡ Processing batch of\", nrow(current_batch), \"documents...\\n\")\n      \n      tryCatch({\n        # Extract features\n        features <- self$feature_extractor$extract_features(current_batch)\n        \n        # Classify documents\n        classified <- self$classifier$classify(features)\n        \n        # Analyze trends\n        trend_analysis <- self$trend_analyzer$analyze_trends(classified)\n        \n        # Check for alerts\n        alerts <- self$alert_system$check_alerts(classified)\n        \n        # Store alerts\n        if (length(alerts) > 0) {\n          for (alert in alerts) {\n            self$alert_queue <- rbind(\n              self$alert_queue,\n              data.table(\n                type = alert$type,\n                severity = alert$severity,\n                message = alert$message,\n                timestamp = alert$timestamp,\n                processed = FALSE\n              ),\n              fill = TRUE\n            )\n          }\n          \n          # Trigger alert callback\n          if (!is.null(self$on_alert_generated)) {\n            self$on_alert_generated(alerts)\n          }\n        }\n        \n        # Update counters\n        self$processed_count <- self$processed_count + nrow(classified)\n        \n        # Trigger document processed callback\n        if (!is.null(self$on_document_processed)) {\n          self$on_document_processed(list(\n            documents = classified,\n            trend_analysis = trend_analysis,\n            batch_size = nrow(classified),\n            total_processed = self$processed_count\n          ))\n        }\n        \n        # Clean up processing buffer\n        if (nrow(self$processing_buffer) > self$batch_size * 5) {\n          self$processing_buffer <- tail(self$processing_buffer, self$batch_size * 3)\n        }\n        \n        cat(\"✅ Batch processed successfully\\n\")\n        \n      }, error = function(e) {\n        self$error_count <- self$error_count + 1\n        warning(\"Batch processing failed: \", e$message)\n        \n        if (!is.null(self$on_error)) {\n          self$on_error(e)\n        }\n      })\n      \n      invisible(self)\n    },\n    \n    get_status = function() {\n      list(\n        is_running = self$is_running,\n        processed_count = self$processed_count,\n        error_count = self$error_count,\n        queue_size = nrow(self$incoming_queue),\n        alert_count = nrow(self$alert_queue[processed == FALSE]),\n        memory_usage_mb = as.numeric(object.size(self$incoming_queue)) / (1024^2)\n      )\n    },\n    \n    get_alerts = function(unprocessed_only = TRUE) {\n      if (unprocessed_only) {\n        return(self$alert_queue[processed == FALSE])\n      } else {\n        return(self$alert_queue)\n      }\n    },\n    \n    mark_alerts_processed = function(alert_ids = NULL) {\n      if (is.null(alert_ids)) {\n        self$alert_queue[, processed := TRUE]\n      } else {\n        self$alert_queue[id %in% alert_ids, processed := TRUE]\n      }\n      invisible(self)\n    },\n    \n    clear_alerts = function() {\n      self$alert_queue <- data.table()\n      invisible(self)\n    },\n    \n    get_recent_activity = function(hours = 1) {\n      cutoff_time <- Sys.time() - hours * 3600\n      recent_data <- self$processing_buffer[processed_at >= cutoff_time]\n      \n      if (nrow(recent_data) > 0) {\n        list(\n          document_count = nrow(recent_data),\n          categories = recent_data[, .N, by = category],\n          priority_distribution = recent_data[, .N, by = priority],\n          avg_transport_score = recent_data[, mean(transport_score, na.rm = TRUE)],\n          processing_rate = nrow(recent_data) / hours\n        )\n      } else {\n        list(\n          document_count = 0,\n          categories = data.table(),\n          priority_distribution = data.table(),\n          processing_rate = 0\n        )\n      }\n    }\n  )\n)\n\n# ============================================================================\n# 2. LIVE DASHBOARD UPDATER\n# ============================================================================\n\n#' Live Dashboard Data Manager\n#' Manages real-time data updates for Shiny dashboard\nLiveDashboardUpdater <- R6Class(\"LiveDashboardUpdater\",\n  public = list(\n    # Configuration\n    update_interval = 3,  # seconds\n    max_history = 1000,   # maximum historical records to keep\n    \n    # State\n    is_active = FALSE,\n    \n    # Data storage\n    live_data = NULL,\n    metrics_history = NULL,\n    \n    # Shiny session\n    session = NULL,\n    \n    initialize = function(session = NULL) {\n      self$session <- session\n      self$live_data <- reactiveValues(\n        recent_documents = data.table(),\n        current_metrics = list(),\n        alerts = data.table(),\n        trend_data = data.table()\n      )\n      \n      self$metrics_history <- data.table(\n        timestamp = as.POSIXct(character()),\n        documents_processed = numeric(),\n        transport_documents = numeric(),\n        high_priority_documents = numeric(),\n        processing_rate = numeric()\n      )\n      \n      cat(\"📊 Live Dashboard Updater initialized\\n\")\n    },\n    \n    connect_to_processor = function(processor) {\n      # Set up callbacks from real-time processor\n      processor$on_document_processed <- function(result) {\n        self$update_dashboard_data(result)\n      }\n      \n      processor$on_alert_generated <- function(alerts) {\n        self$update_alerts(alerts)\n      }\n      \n      cat(\"🔗 Connected to real-time processor\\n\")\n      invisible(self)\n    },\n    \n    start_updates = function() {\n      if (self$is_active) {\n        return(invisible(self))\n      }\n      \n      self$is_active <- TRUE\n      cat(\"🔄 Starting live dashboard updates...\\n\")\n      \n      # Start update loop\n      if (!is.null(self$session)) {\n        observe({\n          invalidateLater(self$update_interval * 1000, self$session)\n          if (self$is_active) {\n            self$refresh_metrics()\n          }\n        })\n      }\n      \n      invisible(self)\n    },\n    \n    stop_updates = function() {\n      self$is_active <- FALSE\n      cat(\"⏸️  Stopped live dashboard updates\\n\")\n      invisible(self)\n    },\n    \n    update_dashboard_data = function(processing_result) {\n      if (!self$is_active) return(invisible(self))\n      \n      tryCatch({\n        # Update recent documents\n        self$live_data$recent_documents <- processing_result$documents\n        \n        # Update metrics\n        current_time <- Sys.time()\n        \n        # Calculate current metrics\n        metrics <- list(\n          total_processed = processing_result$total_processed,\n          batch_size = processing_result$batch_size,\n          processing_rate = processing_result$batch_size / self$update_interval,\n          transport_documents = nrow(processing_result$documents[category == \"Transporte\"]),\n          high_priority = nrow(processing_result$documents[priority == \"Alta\"]),\n          timestamp = current_time\n        )\n        \n        self$live_data$current_metrics <- metrics\n        \n        # Add to metrics history\n        new_metric_row <- data.table(\n          timestamp = current_time,\n          documents_processed = metrics$batch_size,\n          transport_documents = metrics$transport_documents,\n          high_priority_documents = metrics$high_priority,\n          processing_rate = metrics$processing_rate\n        )\n        \n        self$metrics_history <- rbind(self$metrics_history, new_metric_row)\n        \n        # Trim history if too long\n        if (nrow(self$metrics_history) > self$max_history) {\n          self$metrics_history <- tail(self$metrics_history, self$max_history * 0.8)\n        }\n        \n        # Update trend data\n        if (nrow(self$metrics_history) >= 10) {\n          recent_metrics <- tail(self$metrics_history, 20)\n          \n          trend_summary <- recent_metrics[, {\n            list(\n              avg_processing_rate = mean(processing_rate, na.rm = TRUE),\n              total_documents = sum(documents_processed, na.rm = TRUE),\n              peak_rate = max(processing_rate, na.rm = TRUE),\n              transport_percentage = mean(transport_documents / pmax(documents_processed, 1), na.rm = TRUE) * 100\n            )\n          }]\n          \n          self$live_data$trend_data <- trend_summary\n        }\n        \n      }, error = function(e) {\n        warning(\"Dashboard data update failed: \", e$message)\n      })\n      \n      invisible(self)\n    },\n    \n    update_alerts = function(alerts) {\n      if (!self$is_active) return(invisible(self))\n      \n      tryCatch({\n        # Convert alerts to data.table format\n        alert_data <- rbindlist(lapply(alerts, function(alert) {\n          data.table(\n            type = alert$type,\n            severity = alert$severity,\n            message = alert$message,\n            timestamp = alert$timestamp,\n            count = alert$count %||% 1\n          )\n        }), fill = TRUE)\n        \n        # Update reactive alerts\n        self$live_data$alerts <- rbind(self$live_data$alerts, alert_data, fill = TRUE)\n        \n        # Keep only recent alerts (last 24 hours)\n        cutoff_time <- Sys.time() - 24 * 3600\n        self$live_data$alerts <- self$live_data$alerts[timestamp >= cutoff_time]\n        \n      }, error = function(e) {\n        warning(\"Alert update failed: \", e$message)\n      })\n      \n      invisible(self)\n    },\n    \n    refresh_metrics = function() {\n      if (nrow(self$metrics_history) > 0) {\n        # Calculate rolling averages and trends\n        recent_history <- tail(self$metrics_history, 20)\n        \n        if (nrow(recent_history) >= 2) {\n          # Simple trend calculation\n          trend_slope <- with(recent_history, {\n            lm(processing_rate ~ as.numeric(timestamp))$coefficients[2]\n          })\n          \n          # Update current metrics with trend info\n          if (!is.null(self$live_data$current_metrics)) {\n            self$live_data$current_metrics$trend_slope <- trend_slope\n            self$live_data$current_metrics$trend_direction <- ifelse(\n              trend_slope > 0.01, \"increasing\",\n              ifelse(trend_slope < -0.01, \"decreasing\", \"stable\")\n            )\n          }\n        }\n      }\n      \n      invisible(self)\n    },\n    \n    get_dashboard_data = function() {\n      list(\n        recent_documents = self$live_data$recent_documents,\n        current_metrics = self$live_data$current_metrics,\n        alerts = self$live_data$alerts,\n        trend_data = self$live_data$trend_data,\n        metrics_history = self$metrics_history\n      )\n    },\n    \n    generate_summary_report = function() {\n      if (nrow(self$metrics_history) == 0) {\n        return(list(\n          status = \"no_data\",\n          message = \"No processing history available\"\n        ))\n      }\n      \n      # Analysis period\n      start_time <- min(self$metrics_history$timestamp)\n      end_time <- max(self$metrics_history$timestamp)\n      duration_hours <- as.numeric(difftime(end_time, start_time, units = \"hours\"))\n      \n      # Summary statistics\n      summary_stats <- self$metrics_history[, {\n        list(\n          total_documents = sum(documents_processed, na.rm = TRUE),\n          total_transport_docs = sum(transport_documents, na.rm = TRUE),\n          total_high_priority = sum(high_priority_documents, na.rm = TRUE),\n          avg_processing_rate = mean(processing_rate, na.rm = TRUE),\n          peak_processing_rate = max(processing_rate, na.rm = TRUE),\n          min_processing_rate = min(processing_rate, na.rm = TRUE)\n        )\n      }]\n      \n      # Transport document percentage\n      transport_percentage <- if (summary_stats$total_documents > 0) {\n        (summary_stats$total_transport_docs / summary_stats$total_documents) * 100\n      } else {\n        0\n      }\n      \n      # High priority percentage\n      priority_percentage <- if (summary_stats$total_documents > 0) {\n        (summary_stats$total_high_priority / summary_stats$total_documents) * 100\n      } else {\n        0\n      }\n      \n      return(list(\n        status = \"success\",\n        analysis_period = list(\n          start_time = start_time,\n          end_time = end_time,\n          duration_hours = duration_hours\n        ),\n        summary_statistics = list(\n          total_documents_processed = summary_stats$total_documents,\n          transport_documents = summary_stats$total_transport_docs,\n          transport_percentage = round(transport_percentage, 1),\n          high_priority_documents = summary_stats$total_high_priority,\n          priority_percentage = round(priority_percentage, 1),\n          average_processing_rate = round(summary_stats$avg_processing_rate, 2),\n          peak_processing_rate = round(summary_stats$peak_processing_rate, 2)\n        ),\n        alerts_summary = list(\n          total_alerts = nrow(self$live_data$alerts),\n          high_severity_alerts = nrow(self$live_data$alerts[severity == \"high\"]),\n          recent_alerts = nrow(self$live_data$alerts[timestamp >= (Sys.time() - 3600)])  # Last hour\n        )\n      ))\n    }\n  )\n)\n\n# ============================================================================\n# 3. EVENT-DRIVEN ALERT SYSTEM\n# ============================================================================\n\n#' Event-Driven Alert Manager\n#' Manages automated alerts based on legislative document patterns\nAlertManager <- R6Class(\"AlertManager\",\n  public = list(\n    # Configuration\n    alert_rules = NULL,\n    notification_channels = NULL,\n    \n    # State\n    active_alerts = NULL,\n    alert_history = NULL,\n    \n    initialize = function() {\n      # Initialize default alert rules\n      self$alert_rules <- list(\n        high_priority_transport = list(\n          condition = function(data) nrow(data[category == \"Transporte\" & priority == \"Alta\"]) > 0,\n          severity = \"high\",\n          message_template = \"High-priority transport documents detected: {count} documents\",\n          cooldown_minutes = 15\n        ),\n        \n        unusual_volume = list(\n          condition = function(data) nrow(data) > 100,\n          severity = \"medium\",\n          message_template = \"Unusual document volume: {count} documents in batch\",\n          cooldown_minutes = 30\n        ),\n        \n        new_legal_framework = list(\n          condition = function(data) {\n            any(grepl(\"marco regulatório|nova lei|sistema nacional\", data$title, ignore.case = TRUE))\n          },\n          severity = \"high\",\n          message_template = \"Potential new legal framework detected\",\n          cooldown_minutes = 60\n        ),\n        \n        sustainability_focus = list(\n          condition = function(data) {\n            sustainability_docs <- nrow(data[grepl(\"sustentável|verde|carbono|emissão\", title, ignore.case = TRUE)])\n            sustainability_docs > 5\n          },\n          severity = \"medium\",\n          message_template = \"Increased focus on sustainability: {count} related documents\",\n          cooldown_minutes = 45\n        )\n      )\n      \n      # Initialize storage\n      self$active_alerts <- data.table(\n        id = character(),\n        type = character(),\n        severity = character(),\n        message = character(),\n        timestamp = as.POSIXct(character()),\n        acknowledged = logical()\n      )\n      \n      self$alert_history <- data.table(\n        id = character(),\n        type = character(),\n        severity = character(),\n        message = character(),\n        timestamp = as.POSIXct(character()),\n        resolved_at = as.POSIXct(character())\n      )\n      \n      cat(\"🚨 Alert Manager initialized with\", length(self$alert_rules), \"rules\\n\")\n    },\n    \n    add_alert_rule = function(name, condition, severity = \"medium\", \n                             message_template = \"Alert: {name}\", cooldown_minutes = 30) {\n      self$alert_rules[[name]] <- list(\n        condition = condition,\n        severity = severity,\n        message_template = message_template,\n        cooldown_minutes = cooldown_minutes\n      )\n      \n      cat(\"➕ Added alert rule:\", name, \"\\n\")\n      invisible(self)\n    },\n    \n    check_alerts = function(data) {\n      if (nrow(data) == 0) return(invisible(self))\n      \n      current_time <- Sys.time()\n      new_alerts <- list()\n      \n      for (rule_name in names(self$alert_rules)) {\n        rule <- self$alert_rules[[rule_name]]\n        \n        tryCatch({\n          # Check cooldown period\n          last_alert_time <- self$get_last_alert_time(rule_name)\n          if (!is.na(last_alert_time)) {\n            time_since_last <- as.numeric(difftime(current_time, last_alert_time, units = \"mins\"))\n            if (time_since_last < rule$cooldown_minutes) {\n              next  # Skip this rule due to cooldown\n            }\n          }\n          \n          # Check condition\n          if (rule$condition(data)) {\n            # Generate alert\n            alert_id <- paste0(rule_name, \"_\", as.integer(current_time))\n            \n            # Create message with data substitution\n            message <- gsub(\"\\\\{count\\\\}\", nrow(data), rule$message_template)\n            message <- gsub(\"\\\\{name\\\\}\", rule_name, message)\n            \n            new_alert <- data.table(\n              id = alert_id,\n              type = rule_name,\n              severity = rule$severity,\n              message = message,\n              timestamp = current_time,\n              acknowledged = FALSE\n            )\n            \n            # Add to active alerts\n            self$active_alerts <- rbind(self$active_alerts, new_alert)\n            new_alerts[[length(new_alerts) + 1]] <- new_alert\n            \n            cat(\"🚨 Alert triggered:\", rule_name, \"-\", message, \"\\n\")\n          }\n          \n        }, error = function(e) {\n          warning(\"Alert rule \", rule_name, \" failed: \", e$message)\n        })\n      }\n      \n      # Clean up old alerts (move to history)\n      self$cleanup_old_alerts()\n      \n      return(new_alerts)\n    },\n    \n    get_last_alert_time = function(alert_type) {\n      recent_alerts <- self$active_alerts[type == alert_type]\n      if (nrow(recent_alerts) > 0) {\n        return(max(recent_alerts$timestamp))\n      }\n      \n      # Check history as well\n      history_alerts <- self$alert_history[type == alert_type]\n      if (nrow(history_alerts) > 0) {\n        return(max(history_alerts$timestamp))\n      }\n      \n      return(as.POSIXct(NA))\n    },\n    \n    acknowledge_alert = function(alert_id) {\n      self$active_alerts[id == alert_id, acknowledged := TRUE]\n      cat(\"✅ Alert acknowledged:\", alert_id, \"\\n\")\n      invisible(self)\n    },\n    \n    resolve_alert = function(alert_id) {\n      alert_to_resolve <- self$active_alerts[id == alert_id]\n      \n      if (nrow(alert_to_resolve) > 0) {\n        # Move to history\n        resolved_alert <- copy(alert_to_resolve)\n        resolved_alert[, resolved_at := Sys.time()]\n        \n        self$alert_history <- rbind(self$alert_history, resolved_alert, fill = TRUE)\n        \n        # Remove from active alerts\n        self$active_alerts <- self$active_alerts[id != alert_id]\n        \n        cat(\"✅ Alert resolved:\", alert_id, \"\\n\")\n      }\n      \n      invisible(self)\n    },\n    \n    cleanup_old_alerts = function(max_age_hours = 24) {\n      cutoff_time <- Sys.time() - max_age_hours * 3600\n      \n      # Move old acknowledged alerts to history\n      old_alerts <- self$active_alerts[acknowledged == TRUE & timestamp < cutoff_time]\n      \n      if (nrow(old_alerts) > 0) {\n        old_alerts[, resolved_at := Sys.time()]\n        self$alert_history <- rbind(self$alert_history, old_alerts, fill = TRUE)\n        \n        # Remove from active alerts\n        self$active_alerts <- self$active_alerts[!(acknowledged == TRUE & timestamp < cutoff_time)]\n        \n        cat(\"🧹 Cleaned up\", nrow(old_alerts), \"old alerts\\n\")\n      }\n      \n      invisible(self)\n    },\n    \n    get_active_alerts = function(severity = NULL) {\n      if (is.null(severity)) {\n        return(self$active_alerts)\n      } else {\n        return(self$active_alerts[severity == severity])\n      }\n    },\n    \n    get_alert_summary = function() {\n      list(\n        total_active = nrow(self$active_alerts),\n        high_severity = nrow(self$active_alerts[severity == \"high\"]),\n        medium_severity = nrow(self$active_alerts[severity == \"medium\"]),\n        low_severity = nrow(self$active_alerts[severity == \"low\"]),\n        unacknowledged = nrow(self$active_alerts[acknowledged == FALSE]),\n        total_historical = nrow(self$alert_history)\n      )\n    }\n  )\n)\n\n# Helper function for null coalescing\n`%||%` <- function(a, b) if (is.null(a)) b else a\n\ncat(\"✅ Real-Time Analytics Engine fully loaded!\\n\")\ncat(\"   🚀 Streaming processor: ENABLED\\n\")\ncat(\"   📊 Live dashboard updates: ENABLED\\n\")\ncat(\"   🚨 Event-driven alerts: ENABLED\\n\")\ncat(\"   ⚡ Incremental learning: ENABLED\\n\")\ncat(\"   📈 Real-time trend analysis: ENABLED\\n\")\ncat(\"   🔄 Continuous processing: ENABLED\\n\")\n\n# Export main classes\nREAL_TIME_ANALYTICS_CLASSES <- list(\n  RealTimeProcessor = RealTimeProcessor,\n  LiveDashboardUpdater = LiveDashboardUpdater,\n  AlertManager = AlertManager\n)"